import {React} from "react";

export const languages = {
     "한국인": 'Korean', "English": 'eng',
};

export const LOCALE_TEXT = {

    // City List
    "city-list-Amsterdam": {
        "eng": "Amsterdam",
        "dut": "Amsterdam",
        "esp": "Ámsterdam",
        "fra": "Amsterdam",
        "nor": "Amsterdam",
        "arb": "أمستردام",
    }, "city-list-Barcelona": {
        "eng": "Barcelona",
        "dut": "Barcelona",
        "esp": "Barcelona",
        "fra": "Barcelone",
        "nor": "Barcelona",
        "arb": "برشلونة",
    }, "city-list-Buenos Aires": {
        "eng": "Buenos Aires",
        "dut": "Buenos Aires",
        "esp": "Buenos Aires",
        "fra": "Buenos Aires",
        "nor": "Buenos Aires",
        "arb": "بوينس آيرس",
    }, "city-list-Dubai": {
        "eng": "Dubai", "dut": "Dubai", "esp": "Dubái", "fra": "Dubai", "nor": "Dubai", "arb": "دبي",
    }, "city-list-Montreal": {
        "eng": "Montreal",
        "dut": "Montreal",
        "esp": "Montreal",
        "fra": "Montréal",
        "nor": "Montreal",
        "arb": "مونتريال",
    }, "city-list-Nairobi": {
        "eng": "Nairobi", "dut": "Nairobi", "esp": "Nairobi", "fra": "Nairobi", "nor": "Nairobi", "arb": "نيروبي",
    }, "city-list-Singapore": {
        "eng": "Singapore",
        "dut": "Singapore",
        "esp": "Singapur",
        "fra": "Singapour",
        "nor": "Singapore",
        "arb": "سنغافورة",
    }, "city-list-Trondheim": {
        "eng": "Trondheim",
        "dut": "Trondheim",
        "esp": "Trondheim",
        "fra": "Trondheim",
        "nor": "Trondheim",
        "arb": "تروندهايم",
    },
    "city-list-Québec City": {
        "eng": "Québec City",
        "dut": "Québec City",
        "esp": "Ciudad de Quebec",
        "fra": "Ville de Québec",
        "nor": "Québec by",
        "arb": "مدينة كيبيك",
    },

    // Home Page
    'home-page-title': {
        'eng': 'Feeling Nature Seoul',
        'Korean': '필링 네이처 서울',
    }, 'home-page-subtitle': {
        'eng': 'Measuring Biophilic perception using Visual AI',
        'Korean': '비오필리아 인식을 비주얼 AI로 측정하기',
    }, 'home-page-description': {
        'eng': (<>
            You’re invited to take part in a short research survey exploring how people experience natural settings in Seoul.
            Your input will help us understand which environments bring more positive feelings to citizens like you. The survey takes less than 5 minutes to complete. 
            <br/> <br/>
            Participation is entirely voluntary, and your responses will remain anonymous. All data will be used only for scientific research and will never be shared for commercial purposes.
            Thank you for contributing to this research. Together, we can help make Seoul a greener, happier city!
        </>), 'Korean': (<>
            서울의 자연 환경에 대한 시민들의 경험을 알아보기 위한 짧은 연구 설문에 참여해 주세요.
            여러분의 응답은 어떤 환경이 더 긍정적인 감정을 불러일으키는지 이해하는 데 도움이 됩니다. 설문은 5분 이내로 완료할 수 있습니다.
            <br/> <br/>
            참여는 전적으로 자발적이며, 모든 응답은 익명으로 처리됩니다. 수집된 데이터는 과학적 연구 목적으로만 사용되며, 상업적 용도나 제3자에게는 절대 공유되지 않습니다.
            이 연구에 참여해 주셔서 감사합니다. 함께 서울을 더 푸르고, 더 행복한 도시로 만들어가요!
        </>), 
    }, 'home-page-button-start-survey': {
        'eng': 'Start',
        'Korean': '시작하기',
    }, 'home-page-author-title': {
        'eng': 'A project by',
        'Korean': '이 프로젝트는 다음에 의해 진행되었습니다',
    },

    // SurveyCitySelectPage
    'survey-city-select-title': {
        'eng': '1 | Have you lived in Seoul for at least 1 year?',
        'Korean': '1 | 서울에서 1년 이상 거주한 경험이 있습니까? ',
    }, 'survey-city-select-description': {
        'eng': ' After completing the survey, you will be able to come back and repeat it again with Question 1.',
        'Korean': '설문을 완료하신 후, 다시 돌아와 1번 질문부터 설문을 반복하실 수 있습니다.',
    },

    // SurveyImgChoicePage
    'survey-img-choice-title': {
        'eng': 'Which image brings you more positive feelings?',
        'Korean': '어떤 이미지가 더 긍정적인 감정을 불러일으키나요?',
    }, 'survey-img-choice-comment-box-question': {
        'eng': 'Which elements and aspects of the selected image bring you more positive feelings?',
        'Korean': '선택한 이미지의 어떤 요소와 측면이 긍정적인 감정을 유발했나요?',
    }, 'survey-img-choice-submit-button': {
        'eng': 'Next', 'Korean': '다음', 
    },
    'survey-img-choice-comment-placeholder': {
        'eng': 'Please comment on your choice',
        'Korean': '선택한 이유를 간단히 설명해 주세요',
    },

    'survey-img-choice-button-left': {
        'eng': 'Left', 'Korean': '왼쪽', 
    },
    'survey-img-choice-button-right': {
        'eng': 'Right', 'Korean': '오른쪽', 
    },
    'survey-img-choice-loading-text': {
        'eng': 'Loading', 'Korean': '로딩 중', 

    },

    // SurveyPersonalInfoPage
    'survey-personal-info-question-age': {
        'eng': '8 | Please select your age group.',
        'Korean': '8 | 연령대를 선택해 주세요.',
    }, 'survey-personal-info-question-gender': {
        'eng': '9 | Please select the option that describes you best.',
        'Korean': '9 | 본인에게 가장 잘 맞는 항목을 선택해 주세요.',
    },

    'survey-personal-info-question-gender-option-Male': {
        'eng': 'Male', 'Korean': '남성', 
    }, 'survey-personal-info-question-gender-option-Female': {
        'eng': 'Female', 'Korean': '여성',
    }, 'survey-personal-info-question-gender-option-Other': {
        'eng': 'Other', 'Korean': '기타', 
    }, 'survey-personal-info-question-gender-option-Prefer not to answer': {
        'eng': 'Prefer not to answer',
        'Korean': '응답하지 않음',
    },
    'survey-personal-info-submit-button': {
        'eng': 'Submit', 'Korean': '제출하기',
    },

    // Thank you
    'thank-you-title': {
        'eng': 'Thank you for your participation!',
        'Korean': '참여해 주셔서 감사합니다!',
    }, 'thank-you-description': {
        'eng': 'Go back to the home screen and take the survey for any other city where you have lived for at least 1 year.',
        'Korean': '홈 화면으로 돌아가 1년 이상 거주한 다른 도시의 설문도 참여해 보세요.',
    }, 'thank-you-button-start-again': {
        'eng': 'Start Again',
        'Korean': '다시 시작하기',
    }, 'thank-you-form-description': {
        'eng': 'Would you like to know more about BIOPOLIS? Get in touch with us!',
        'Korean': 'BIOPOLIS에 대해 더 알고 싶으신가요? 저희에게 연락 주세요!',
    }, 'thank-you-form-full-name': {
        'eng': 'Full Name',
        'Korean': '이름',
    }, 'thank-you-form-email': {
        'eng': 'Email',
        'Korean': '이메일',
    }, 'thank-you-form-message': {
        'eng': 'Message', 'Korean': '메시지',
    }, 'thank-you-form-submit-button': {
        'eng': 'Send', 'Korean': '보내기', 
    }

}

export const DEFAULT_LANG = 'eng';

export const locale_text_raw =
    (lang, identifier) => (LOCALE_TEXT[identifier][lang] || LOCALE_TEXT[identifier][DEFAULT_LANG]);
export const locale_text = (lang, identifier) => {
    const text = locale_text_raw(lang, identifier);
    if (lang === 'arb') {
        return (
            <p style={{margin: 0}}>
                {text}
            </p>
        )
    }


    return text;
};
